from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

import pytest

from docich.hanjuku_speedrun.hanjuku.flows.prompts import observe_events
from docich.hanjuku_speedrun.hanjuku.orchestrator import _load_save_label, decide
